
import mongoose from "mongoose";

const browserInstallationSchema = new mongoose.Schema(
  {
    // Company reference
    organization: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Organization",
      required: true,
      index: true,
    },

    // Employee using this browser installation
    employee: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },

    // Unique installation identifier generated by extension
    installationId: {
      type: String,
      required: true,
      unique: true,
      immutable: true,
    },

    // Browser information
    browser: {
      type: String,
      enum: ["chrome", "edge"],
      required: true,
      default: "chrome",
    },

    browserVersion: {
      type: String,
      default: null,
    },

    // Extension version
    extensionVersion: {
      type: String,
      required: true,
    },

    // Public key used for installation authentication
    credentialPublicKey: {
      type: String,
      default: null,
      select: false,
    },

    // Installation status
    status: {
      type: String,
      enum: ["pending", "active", "revoked"],
      default: "pending",
      index: true,
    },

    // Enrollment information
    enrolledAt: {
      type: Date,
      default: null,
    },

    // Last successful heartbeat
    lastSeenAt: {
      type: Date,
      default: null,
    },

    // Revocation information
    revokedAt: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
    versionKey: false,
  }
);

// Find installations belonging to an organization
browserInstallationSchema.index({
  organization: 1,
  status: 1,
});

// Find installations belonging to an employee
browserInstallationSchema.index({
  organization: 1,
  employee: 1,
  status: 1,
});

const BrowserInstallation = mongoose.model(
  "BrowserInstallation",
  browserInstallationSchema
);

export default BrowserInstallation;
